procesaTodos=false;window.minall=function(){procesaTodos=true;$("#toolsPantalla").append($("<button/>").addClass("btn btn-danger").html("Cancelar").prop("id","btnCancelar").on("click",()=>{procesaTodos=false;$(".btn-send-email").show().parent().find("span").remove();$("#btnEnviaATodos").show().removeAttr("disable");$(this).remove();$(".btn-send-email").removeClass("pending")}));$(".btn-send-email").hide();$(".btn-send-email").each(function(){exb=$(this).attr("usr_id");$(this).addClass("pending").prop("id",exb).parent().append($("<span/>").empty().html("pendiente"))})};window.enviarEmailATodos=function(screen){if($(".pending:first-child").length==0){$("#btnEnviaATodos").show().removeAttr("disable");$("#btnCancelar").remove();return false}id=$(".pending:first-child").attr("usr_id");anio=$(".pending:first-child").attr("ejercicio");if(id!=undefined&&procesaTodos==true){preparaBotonTabla(id);comunica(screen,{metodo:"enviaPasswords",id:id,ejercicio:anio})}else{$("#btnEnviaATodos").show().removeAttr("disable")}};window.preparaBotonTabla=function(id){$("#"+id).removeClass("pending").addClass("processing").parent().append($("<i/>").addClass("fa fa-spin fa-spinner")).attr("id","td_"+id).find("span").remove();$("#"+id).parent().append($("<span/>").html("procesando"))};